service.method:

SELECT COMPANY_CODE
      ,COMPANY_NAME_LOC
  FROM SCMGL
 WHERE HOUSE_CODE       = ${session.HOUSE_CODE}
   AND COMPANY_CODE     = $S{COMPANY_CODE}
   AND (    1=1
   		AND COMPANY_NAME_LOC LIKE '%' || $S{F_KEYWORD} || '%'
   		 OR COMPANY_CODE     LIKE '%' || $S{F_KEYWORD} || '%'
   )
